#!/bin/bash# Startup script for auth-service# Creates profiles tables first, then runs Django migrationsset -eecho "Creating profiles tables with raw SQL..."python manage.py dbshell <<EOFCREATE TABLE IF NOT EXISTS profiles_user (    id BIGSERIAL PRIMARY KEY,    password VARCHAR(128) NOT NULL,    last_login TIMESTAMP,    is_superuser BOOLEAN NOT NULL DEFAULT FALSE,    username VARCHAR(150) NOT NULL UNIQUE,    first_name VARCHAR(150) NOT NULL DEFAULT '',    last_name VARCHAR(150) NOT NULL DEFAULT '',    email VARCHAR(254) NOT NULL DEFAULT '',    is_staff BOOLEAN NOT NULL DEFAULT FALSE,    is_active BOOLEAN NOT NULL DEFAULT TRUE,    date_joined TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,    "userId" UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),    profile_picture VARCHAR(100),    cover_photo VARCHAR(100),    role VARCHAR(20) NOT NULL DEFAULT 'STUDENT');CREATE INDEX IF NOT EXISTS profiles_user_role_idx ON profiles_user(role);CREATE INDEX IF NOT EXISTS profiles_user_userId_idx ON profiles_user("userId");CREATE INDEX IF NOT EXISTS profiles_user_username_idx ON profiles_user(username);CREATE TABLE IF NOT EXISTS profiles_userprofile (    id BIGSERIAL PRIMARY KEY,    bio TEXT NOT NULL DEFAULT '',    headline VARCHAR(255) NOT NULL DEFAULT '',    location VARCHAR(100) NOT NULL DEFAULT '',    is_private BOOLEAN NOT NULL DEFAULT FALSE,    joined_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,    user_id BIGINT NOT NULL UNIQUE REFERENCES profiles_user(id) ON DELETE CASCADE);CREATE INDEX IF NOT EXISTS profiles_userprofile_user_id_idx ON profiles_userprofile(user_id);CREATE TABLE IF NOT EXISTS profiles_studentprofile (    id BIGSERIAL PRIMARY KEY,    enrollment_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,    student_id VARCHAR(50) UNIQUE,    grade_level VARCHAR(50) NOT NULL DEFAULT '',    is_active BOOLEAN NOT NULL DEFAULT TRUE,    last_activity TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,    user_id BIGINT NOT NULL UNIQUE REFERENCES profiles_user(id) ON DELETE CASCADE,    user_profile_id BIGINT REFERENCES profiles_userprofile(id) ON DELETE CASCADE);CREATE INDEX IF NOT EXISTS profiles_studentprofile_user_id_idx ON profiles_studentprofile(user_id);CREATE TABLE IF NOT EXISTS profiles_teacherprofile (    id BIGSERIAL PRIMARY KEY,    joined_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,    teacher_id VARCHAR(50) UNIQUE,    department VARCHAR(100) NOT NULL DEFAULT '',    designation VARCHAR(100) NOT NULL DEFAULT '',    qualifications TEXT NOT NULL DEFAULT '',    specialization VARCHAR(255) NOT NULL DEFAULT '',    experience_years INTEGER NOT NULL DEFAULT 0,    bio TEXT NOT NULL DEFAULT '',    website VARCHAR(200) NOT NULL DEFAULT '',    linkedin VARCHAR(200) NOT NULL DEFAULT '',    is_verified BOOLEAN NOT NULL DEFAULT FALSE,    is_active BOOLEAN NOT NULL DEFAULT TRUE,    can_create_courses BOOLEAN NOT NULL DEFAULT TRUE,    user_id BIGINT NOT NULL UNIQUE REFERENCES profiles_user(id) ON DELETE CASCADE,    user_profile_id BIGINT REFERENCES profiles_userprofile(id) ON DELETE CASCADE);CREATE INDEX IF NOT EXISTS profiles_teacherprofile_user_id_idx ON profiles_teacherprofile(user_id);EOFecho "Faking profiles initial migration..."python manage.py migrate profiles 0001 --fakeecho "Running Django migrations..."python manage.py migrateecho "Collecting static files..."python manage.py collectstatic --noinputecho "Starting Gunicorn server..."gunicorn auth_service.wsgi:application --bind 0.0.0.0:8001 --workers 4 --timeout 120 --access-logfile - --error-logfile -